// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";

import { buildMissingEdgeQueryBatches } from "../../../main/frontend/graph-explorer/graph-discovery.ts";

const entity = (index) => `http://example.org/entity/${index}`;

test("missing-edge discovery covers every ordered pair with batched VALUES clauses", () => {
  const ids = Array.from({ length: 7 }, (_, index) => entity(index));
  const batches = buildMissingEdgeQueryBatches(ids, {
    sourceBatchSize: 3,
    targetBatchSize: 4,
  });

  assert.equal(batches.length, 6);
  assert.ok(
    batches.every(
      (batch) =>
        batch.query.includes("VALUES ?source") &&
        batch.query.includes("VALUES ?target") &&
        batch.query.includes("?source ?predicate ?target") &&
        batch.query.includes("FILTER(?source != ?target)"),
    ),
  );

  const coveredPairs = new Set();
  batches.forEach((batch) => {
    batch.sourceIds.forEach((source) => {
      batch.targetIds.forEach((target) => {
        if (source !== target) coveredPairs.add(`${source}\u0000${target}`);
      });
    });
  });
  assert.equal(coveredPairs.size, ids.length * (ids.length - 1));
});

test("unsafe and duplicate IRIs are omitted before queries are built", () => {
  const batches = buildMissingEdgeQueryBatches(
    [entity(1), entity(1), "not an iri", entity(2)],
    { sourceBatchSize: 1, targetBatchSize: 10 },
  );

  assert.equal(batches.length, 2);
  assert.ok(batches.every((batch) => !batch.query.includes("not an iri")));
  assert.deepEqual(
    [...new Set(batches.flatMap((batch) => batch.targetIds))],
    [entity(1), entity(2)],
  );
});

test("large graphs are split into bounded endpoint-friendly queries", () => {
  const ids = Array.from({ length: 300 }, (_, index) => entity(index));
  const batches = buildMissingEdgeQueryBatches(ids, {
    sourceBatchSize: 24,
    targetBatchSize: 120,
  });

  assert.equal(batches.length, 39);
  assert.ok(batches.every((batch) => batch.sourceIds.length <= 24));
  assert.ok(batches.every((batch) => batch.targetIds.length <= 120));
  assert.ok(batches.every((batch) => batch.query.length < 150_000));
});

test("invalid batch sizes fall back without hanging or emitting empty batches", () => {
  const ids = [entity(1), entity(2), entity(3)];
  for (const options of [
    { sourceBatchSize: 0, targetBatchSize: 0 },
    { sourceBatchSize: Number.NaN, targetBatchSize: Number.POSITIVE_INFINITY },
    { sourceBatchSize: -4.8, targetBatchSize: -2.1 },
  ]) {
    const batches = buildMissingEdgeQueryBatches(ids, options);
    assert.equal(batches.length, 1);
    assert.deepEqual(batches[0].sourceIds, ids);
    assert.deepEqual(batches[0].targetIds, ids);
    assert.match(batches[0].query, /VALUES \?source/);
  }
});
